user_prompt:
{"objective": "Implemente ingestão idempotente de webhooks num módulo CommonJS para Node 24. O adaptador HTTP já existe. Exporte initialize(db) e ingest(db, {tenantId,eventId,payload}), síncronas, com db de node:sqlite. Todos os campos são strings validadas pelo adaptador. A tabela effects deve expor tenant_id, event_id e payload. A primeira entrega retorna accepted. A repetição do mesmo evento e payload retorna duplicate sem novo efeito. A mesma chave com payload diferente retorna conflict sem sobrescrever o original. A chave inclui o tenant. O efeito precisa ser persistente e uma falha de escrita deve permitir nova tentativa. Sem serviços ou dependências externas. Banco novo de laboratório.", "role": "tech_lead_design", "task": "Definir a arquitetura e as garantias de atomicidade e idempotência, incluindo a chave por tenant e o tratamento de falhas de escrita. Retorne {"design":"decisões e critérios"}.", "context": ""use strict";

function initialize(db) {
  db.exec(`
    CREATE TABLE IF NOT EXISTS effects (
      tenant_id TEXT NOT NULL,
      event_id TEXT NOT NULL,
      payload TEXT NOT NULL
    );
  `);
}

function ingest(db, { tenantId, eventId, payload }) {
  db.prepare("INSERT INTO effects VALUES (?, ?, ?)").run(tenantId, eventId, payload);
  return "accepted";
}

module.exports = { initialize, ingest };
"}
